#!/usr/bin/env python3
"""Build step for the Observatory design system (stdlib only).

    python3 -I build.py           regenerate components.iife.js and the token contract in components.css
    python3 -I build.py --check   fail (exit 1) if either is stale or the contract names an undefined token

1. components.iife.js: components.js with `export` removed, wrapped in an IIFE that sets window.Observatory.
   Browsers refuse ES modules over file://, so pages opened from disk load this file instead.
2. Token contract: check_tokens.py resolves var() names per file. components.css reads its tokens from
   tokens.css, so the names it reads are listed between @contract-start and @contract-end. This step
   regenerates that list from the var() calls and checks that tokens.css defines every one.
"""
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
P = lambda name: os.path.join(HERE, name)
read = lambda name: open(P(name), encoding="utf-8").read()


def build_iife():
    src = read("components.js")
    if re.search(r"^\s*import\s", src, re.M):
        sys.exit("components.js must not import anything")
    names = re.findall(r"^export\s+(?:async\s+)?(?:function\*?|const|let|class)\s+([A-Za-z_$][\w$]*)", src, re.M)
    body = re.sub(r"^export\s+", "", src, flags=re.M)
    body = "\n".join(("  " + line) if line.strip() else "" for line in body.split("\n"))
    return (
        "/* GENERATED by build.py from components.js. Do not edit; run `python3 -I build.py`.\n"
        " * Classic-script build for pages opened over file://. Exposes window.Observatory. */\n"
        "(function (global) {\n  \"use strict\";\n" + body.rstrip() + "\n\n"
        "  global.Observatory = Object.freeze({ " + ", ".join(names) + " });\n"
        "})(typeof window !== \"undefined\" ? window : globalThis);\n"
    ), names


def build_contract(css, tokens):
    start, end = css.index("@contract-start"), css.index("@contract-end")
    outside = css[:start] + css[end:]
    used = sorted(set(re.findall(r"var\((--[\w-]+)", outside)))
    local = set(re.findall(r"(--[\w-]+)\s*:", outside))
    defined = set(re.findall(r"(--[\w-]+)\s*:", tokens))
    external = [u for u in used if u not in local]
    missing = [u for u in external if u not in defined]
    lines, row = [], []
    for name in external:
        row.append(name + ": tokens;")
        if len(" ".join(row)) > 92:
            lines.append(" *   " + " ".join(row[:-1])); row = row[-1:]
    if row:
        lines.append(" *   " + " ".join(row))
    block = "@contract-start\n" + "\n".join(lines) + "\n * @contract-end"
    head = css[:start]
    tail = css[end + len("@contract-end"):]
    return head + block + tail, external, missing


def main():
    check = "--check" in sys.argv
    iife, names = build_iife()
    css = read("components.css")
    new_css, external, missing = build_contract(css, read("tokens.css"))
    problems = []
    if missing:
        problems.append("components.css reads tokens that tokens.css does not define: " + ", ".join(missing))
    if check:
        if not os.path.exists(P("components.iife.js")) or read("components.iife.js") != iife:
            problems.append("components.iife.js is stale")
        if new_css != css:
            problems.append("token contract in components.css is stale")
    else:
        open(P("components.iife.js"), "w", encoding="utf-8").write(iife)
        open(P("components.css"), "w", encoding="utf-8").write(new_css)
    for p in problems:
        print("build:", p)
    print("%d exports, %d contract tokens, %d problem(s)" % (len(names), len(external), len(problems)))
    sys.exit(1 if problems else 0)


if __name__ == "__main__":
    main()
